select privilege_id, count(user_id) pvCount, count(distinct user_id) as countNum from author_privilege_pv_logs where user_id is not null and privilege_id in
#{item}
AND deleted = 0 group by privilege_id

SELECT l.privilege_id AS productId, a.name AS productName, COUNT(DISTINCT l.user_id) AS uv FROM author_privilege_pv_logs l INNER JOIN author_privilege_set a ON a.id = l.privilege_id WHERE l.privilege_id IN
#{id}
AND l.create_time >= #{startTime}
AND l.create_time <= #{endTime}
AND a.deleted = 0 GROUP BY l.privilege_id, a.name

SELECT COUNT(DISTINCT user_id)
FROM author_privilege_pv_logs
WHERE
author_id = #{authorId}

    AND privilege_id = #{privilegeId}

AND create_time >= #{startTime}
AND create_time <= #{endTime}
AND deleted = 0
